CREATE OR REPLACE FUNCTION public.sit_place(p_on_deed boolean, p_height double precision, p_water boolean, p_swirl boolean, p_stale boolean, p_stone boolean)
 RETURNS TABLE(place double precision, said text)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare v_by text[] := '{}';
begin
  place := 1;
  if p_on_deed then
    place := place * sit_yard();
    v_by := v_by || ('own yard ×' || sit_yard());
  end if;
  -- High, wild ground is what the paths are walked on.
  if p_height > sit_thin_at() then
    place := place * sit_thin();
    v_by := v_by || ('over ' || to_char(sit_thin_at() / 10.0, 'FM990.0') || ' m high ×' || sit_thin());
  elsif p_height > sit_high_at() and not p_on_deed then
    place := place * sit_high();
    v_by := v_by || ('over ' || to_char(sit_high_at() / 10.0, 'FM990.0') || ' m high, off your settlement ×' || sit_high());
  end if;
  if p_water then
    place := place * sit_water();
    v_by := v_by || ('feet in water ×' || sit_water());
  end if;
  if p_swirl then
    place := place * sit_swirl();
    v_by := v_by || sit_swirl_said();
  end if;
  if p_stone then
    place := place * sit_stone();
    v_by := v_by || sit_stone_said();
  end if;
  if p_stale then
    place := place * sit_stale();
    v_by := v_by || sit_stale_said();
  end if;
  said := 'Meditation and Calm gained: ' || coalesce(nullif(array_to_string(v_by, ', '), ''), 'no place modifier') || '.';
  return next;
end $function$
